import Foundation

enum KanaKanjiSeedDictionary {
    // Minimal fallback seed used until a preprocessed Sudachi index is supplied.
    static let seed: [String: [String]] = [
        "あい": ["愛", "藍", "会い", "あい"],
        "あお": ["青", "蒼", "あお"],
        "あさ": ["朝", "あさ"],
        "あした": ["明日", "あした"],
        "あなた": ["あなた", "貴方"],
        "ありがとう": ["ありがとう", "有難う"],
        "いえ": ["家", "いえ"],
        // くると: 辞書登録は クルト(Kurt)rank0 と 久留戸 の固有名詞2件だけで、来ると は
        // 来る の活用供給。名詞+くると が全部 〜クルト になっていた(ユーザ指定 2753)
        "くると": ["来ると", "くると", "クルト"],
        // おきた: 基底順が 沖田0/オキタ1/置田2/起多3/冲田4… と固有名詞ばかりで、日常最頻の
