        // 起きた を先頭、次に最頻の姓 沖田。オキタ は5番目に下がる(ユーザ指定 2753)
        "おきた": ["起きた", "沖田", "置田", "起多"],
        // Sudachi の基底順が 帰還0/機関1/貴簡2/飢寒3/亀鑑4/期間5 で、日常最頻の 期間 が5位(2722)。
        // 連文節は LM(機関 4591+の985 < 期間 4816+の1233)で 機関の を採っていたが、単文節先頭を
        // 期間 に揃えると 語+助詞1字 のボーナス(2720)が効いて きかんの→期間の になる
        "きかん": ["期間", "機関", "帰還", "器官", "基幹"],
        // 勝ち/価値 が先頭、単独の 勝(かち)は後ろ(ユーザ指定 3331)
        "かち": ["勝ち", "価値", "カチ", "徒", "可知", "勝"],
        // 支店 が先頭(ユーザ指定 3328)。辞書の rank は 視点 が先頭
        "してん": ["支店", "視点", "始点", "支点", "指点", "熾天"],
        // 変 が先頭、次に 辺(ユーザ指定 3526)。辞書の rank は ヘン/へん/遍 が先頭、LM 実勢は 編 4414 が最安で
        // 編に/編な が先頭に出ていた。へんに/へんな/へんで の合成にも波及する
        "へん": ["変", "辺", "編", "片", "偏"],
        // 照明 が先頭、次に 証明(ユーザ指定 3526)。辞書の rank は 召命 が先頭、LM は 証明 4969 < 照明 5636
        "しょうめい": ["照明", "証明", "章名", "正銘", "召命", "招命", "詔命"],
        // 失くした が先頭(ユーザ指定 3526)。なくす の辞書順は 無くす/喪くす/なくす/亡くす/失くす で、た形は 亡くした が先頭だった。
        // たい形は「無くしたい」(物を無くしたい)が日常なので別に並べる(活用形そのものの seed。かかれ* と同型)
        "なくした": ["失くした", "亡くした", "無くした", "なくした"],
        "なくしたい": ["無くしたい", "失くしたい", "亡くしたい", "なくしたい"],
        // 連用形 なくし: 連文節は 気+なくし+た に割り、語幹 LM 判定(3395)で LM 未収録の 失くし を作らないため、
        // はいるきなくした の変種に 入る気失くした/入る気なくした が出なかった(ユーザ指定 3537: 2・3 番目に)
        "なくし": ["無くし", "なくし", "失くし", "亡くし"],
        // 教本 が先頭(ユーザ指定 3537)。辞書順は 狂奔(6518)/教本(7395)/経本(7404)で、LM は 教本 6911 < 狂奔 8139
        "きょうほん": ["教本", "経本", "狂奔", "きょうほん"],
        // 尽き始めて が先頭(ユーザ指定 3537)。基底 つく の並び(着く/付く/突く/就く)は変えず、はじめ* の複合だけ
        "つきはじめて": ["尽き始めて", "着き始めて", "付き始めて", "突き始めて", "就き始めて", "つき始めて"],
        "つきはじめた": ["尽き始めた", "着き始めた", "付き始めた", "突き始めた", "就き始めた", "つき始めた"],
        "つきはじめる": ["尽き始める", "着き始める", "付き始める", "突き始める", "就き始める", "つき始める"],
        // て(手)は 1 字の助詞と同形で 手+格助詞 の合成が作られず、てで/てに が候補なし(かなだけ)だった(ユーザ報告 3537)
        "てで": ["手で", "てで"],
        "てに": ["手に", "てに"],
        // 急な が先頭、人名の 喜友名(辞書 rank 0)は 2 番目(ユーザ指定 3537)。旧な/九な の X+な 合成は後ろに残る
        "きゅうな": ["急な", "喜友名", "きゅうな"],
        // 再度 が先頭、次に 彩度(ユーザ指定 3526)。辞書の rank は サイド 1082 が先頭
        "さいど": ["再度", "彩度", "サイド", "砕土", "道祖土", "済度"],
        // くむ: 組む が先頭(ユーザ指定 3526)。辞書の rank は 汲む が先頭で、と+くまないと が 汲まないと になっていた。
        // 辞書形の seed は活用派生(組まない/組んで)と合成にも波及する
        "くむ": ["組む", "汲む", "酌む", "くむ"],
        // おくれる: 遅れる を先頭のまま 送れる を 2 番目に(3530)。連文節の活用取得幅(上位 3 件)に 送れる が入らず、
        // べいこくにおくれれば の候補に 送れれば が出なかった。seed 持ちの読みは取得幅が広がる
        "おくれる": ["遅れる", "送れる", "後れる", "贈れる", "おくれる"],
        // ためそう/ためそうと: 試そう(試す の意志形)が先頭(ユーザ指定 3526)。連文節は 溜め+そう+と(ため→そう 4488)が
        // 試そう+と に勝っていた。活用形そのものの seed(かかれ* と同型)
        "ためそう": ["試そう", "ためそう", "溜めそう", "貯めそう"],
        "ためそうと": ["試そうと", "ためそうと", "溜めそうと", "貯めそうと"],
        // へんな: 変な が先頭、次に地名の 平安名(ユーザ指定 3526)。編な/片な/偏な/辺な は seed の後ろに回る
        "へんな": ["変な", "平安名", "へんな", "ヘンナ", "指甲花"],
        // いためる: 炒める が先頭、次に 痛める/傷める、かなは末尾(ユーザ指定 3526)。辞書の rank は 痛める/いためる/イタめる
        "いためる": ["炒める", "痛める", "傷める", "撓める", "イタめる", "いためる"],
        // むす: 蒸す が先頭(ユーザ指定 3526)。辞書の rank は 生す が先頭で、むすんだけど の 2 位が 生すんだけど だった
        "むす": ["蒸す", "生す", "掬す", "むす"],
        // 地名の 堺 が先頭(ユーザ指定 3327)。辞書の rank は 界 が先頭だが、さかい 単独の 界 は日常ではまず使わない
        "さかい": ["堺", "境", "坂井", "酒井", "界"],
        // ごく: 基底順が 極く0/国1/ごく2/極3/石4/ゴク5/獄6/語句7 で 語句 が末尾近く。かな ごく(副詞)の次に
        // 語句 を置く(ユーザ指定 2722)。国/石/ゴク は従来どおり後続のフィルタに任せる
