        // さらい〜: 再来週/再来月/再来年 は辞書 rank0 だが LM 未収録(word_cost 12649/10338/10315=収穫底値扱い)で、
        // 連文節が さ+来週(さ来週/さ来襲/さ来秋…)を組んで先頭に置いていた。読み全体の seed は連文節を
