        "さらいげつ": ["再来月"],
        "さらいねん": ["再来年"],
        // たんご: 基底順 タンゴ0/端午1/丹後2/単語3。日常最頻の 単語 を先頭に(ユーザ指定の並び 2722)
        "たんご": ["単語", "丹後", "端午", "タンゴ"],
        // せいほう: 基底順 青峰0/西方1/製法2。日常語の 製法 を先頭に(ユーザ指定 2728)
        "せいほう": ["製法", "西方", "正方"],
        // なんい: 基底順 難易0/南緯1。難易 の頻度はほぼ 難易度(別語・rank0 の1ノード)由来で、単独の 難易 は
        // 南緯 より稀(ユーザ指定 2730)。LM も 南緯 6742 < 難易 7792
        "なんい": ["南緯", "難易"],
        // たる: 単独入力は名詞 樽 を先頭に(足る は文の切れ端でしか出ない。ユーザ指定 2731)
