        // かおり: 人名(香/薫)より一般名詞 香り を先頭に(ユーザ指定 2731)
        "かおり": ["香り", "香", "薫り", "薫"],
        // 色+がかる(紫がかった 等)の接尾動詞はかなが正書。連文節で が+買った に割れないよう1ノードで供給(2731)
        "がかった": ["がかった"],
        "がかる": ["がかる"],
        "がかって": ["がかって"],
        "がかっている": ["がかっている"],
        "がかってる": ["がかってる"],
