        // たんにん: 単文節は タンニン 先頭だが連文節は LM(担任 6571<タンニン 7079)で 滑らかな担任 になっていた。
        // ワイン用途優先で連文節も タンニン 先頭(multiClauseSeedFirstLMOverrideReadings。ユーザ指定 2735)
        "たんにん": ["タンニン", "担任"],
        // こうしゅう: 単文節は 甲州(vin.plist)先頭だが連文節は 公衆(5717、→の 1362)に負け 公衆の/公衆の可否 だった。
        // seed 順ボーナスで 甲州 を連文節でも先頭に(ユーザ指定 2735)
