        // かひ: 果皮(wc 7404、可否/歌碑 と同値帯)が連文節に届かず 甲州の可否 になっていた。ワイン用途で 果皮 先頭
        "かひ": ["果皮", "可否", "歌碑"],
        // しよう: 辞書 rank は 至要/仕様/枝葉/シヨウ/使用 の順で、日常語の 使用 が 5 番目。
