        // しゅどう: 手動 を先頭に(ユーザ指定の並び 3436。辞書は 主導/主働/主動/手動 …)。朱銅 は辞書の表記
        "しゅどう": ["手動", "主導", "主働", "首藤", "主動", "朱銅", "主胴", "衆道", "酒道"],
