        "からくち": ["辛口"],
        "あまくち": ["甘口"],
        // きこう: 辞書 rank が 機構/寄港/気功/奇行/器工… と続き 気候 は 19 番目(帰耕/柵養 の後ろ)。
        // 日常語の 気候 を先頭に。連文節も unigram 機構 4758 < 気候 5091 で 機構は温暖です に
