        "きこう": ["気候", "機構", "寄港", "気功", "紀行", "寄稿"],
        // のみかた: 飲み方(派生 1 ノード 7200)が の+見方(6778)にわずかに負けていた。ちょっとだけ優先(2881、ユーザ指定)
        "のみかた": ["飲み方"],
        // かきかた: 書き方 を 描き方 より少し前に(ユーザ指定 2881)
        "かきかた": ["書き方", "描き方"],
        // かつらむき: 辞書 rank は 桂剥き/カツラ剥き/桂むき。カタカナは最後に(ユーザ指定 2880)
        "かつらむき": ["桂剥き", "桂むき", "カツラ剥き"],
        // はっこう: 発酵 は抑制済み(ユーザは 醗酵 と書く)。LM は 醗酵 7190 ≫ 発行 4301 で 発行 が
