        "はっこう": ["醗酵", "発効", "発行", "発光"],
        // じょうりゅう: 辞書 rank0 は 蒸溜 だが LM は 蒸留 6510 のみ収録で 蒸溜 は未収録。
        // ユーザー指定で 蒸溜 を優先(2879)
        "じょうりゅう": ["蒸溜", "蒸留", "上流"],
        // にっしょく/げっしょく: 蝕 を 食 より優先(ユーザ方針。蒸溜>蒸留、沈澱>沈殿 と同系。2896)。辞書 rank は 日食/日蝕、月食/月色/月蝕
        "にっしょく": ["日蝕", "日食"],
        "げっしょく": ["月蝕", "月食"],
        // こうにん: 辞書 rank は 公認/肯認/降任/後任。日常語の 後任 を 2 番手に(ユーザ指定 2898)。肯認/降任 は法律・人事の稀語
        "こうにん": ["公認", "後任", "降任", "肯認"],
        // しょうたい: 招待/正体/尚泰(補助語彙の琉球国王)/小隊 の順(ユーザ指定 2901)。かな しょうたい は末尾へ
        "しょうたい": ["招待", "正体", "尚泰", "小隊"],
        // しろ: 辞書 rank は 志魯(固有名)/しろ/シロ/白/城。BCCWJ でも 白 ≫ 城、かなは する の命令形でもあるので 3 番手(ユーザ指定 2904)
        "しろ": ["白", "城", "しろ"],
        // まぶた: 辞書 rank は 瞼/マブタ/目蓋/眼蓋/眼ぶた/まぶた で、実機では交ぜ書きの 眼ぶた が先頭だった。かなが正書(ユーザ指定 2905)
        "まぶた": ["まぶた", "瞼", "目蓋", "眼蓋"],
        // さんか: 辞書 rank は 賛歌0/山窩1/参加2/傘下3/山下4/サンカ5/酸化6… で、日常最頻の 参加 が3位、
        // 酸化 が6位だった。頻度順に並べ替える(ユーザ指定 3202)。旧字体の 讚歌 は同時に抑制した
        "さんか": ["参加", "酸化", "傘下", "讃歌", "賛歌", "山窩", "産科"],
        // どうき: 辞書 rank は 動悸0/同期1/同機2/動気3/同気4/銅器5/動機6 で、日常最頻の 同期/動機 が
