        // おいやすい: 老いる(一段ルールが先)族が 追う/負う 族より前に出ていた(ユーザ指定 2916)。かな形を先、易い形を後に
        "おいやすい": ["追いやすい", "老いやすい", "追い易い", "老い易い"],
