        // きゅうせい: 辞書 rank は 旧政/急性/九成/急逝/九星/旧制/救世/旧姓(ユーザ指定 2910)
        "きゅうせい": ["旧姓", "急性", "急逝", "旧制"],
        // よかった: かなが正書、良かった は 2 番手(ユーザ指定 2910)
        "よかった": ["よかった", "良かった"],
        // そうか: 辞書 rank は 瘡痂/創価/爽果/ソウカ/創化/僧家/喪家/孀嫁… で、見たこともない語が並ぶ。
        // 相槌のかな そうか が正書で先頭、2 番手は地名の 草加(ユーザ指定 2923)
        "そうか": ["そうか", "草加", "創価"],
        // いし: 辞書 rank は 石/頤使/甃/医師/移祀/縊死/頤指/意志/意思 で、見たこともない語が前に出ていた(ユーザ指定 2908)
        "いし": ["意思", "医師", "石", "意志", "遺志"],
        // 話し言葉優先の同音語順(2906、ユーザ方針: 書き言葉と食い違えば話し言葉)。CEJC(日本語日常会話コーパス)短単位語彙表で
        // 同読み名詞の 1 位が écritu の先頭と違う 69 読み。[CEJC 1 位, BCCWJ 1 位, それまでの écritu 先頭] の順。CEJC 頻度 10 未満と
