        "はん": ["版", "班", "藩", "はん", "ハン"],
        "ろん": ["論", "ロン", "崙", "ろん"],
        // ママぁ(読み違いの誤エントリ)は suppr 側で抑制
        "まま": ["ママ", "まま", "侭", "間々"],
