        // 末尾へ降格(れいは の処方。ユーザー指定 2627)
        "るい": ["類", "ルイ", "塁", "累"],
        // せんせんげつ: Sudachi は 先先月(踊り字なし)だけを収穫底値 wc11402 で持ち、
        // 底値降格で沈むため候補ゼロ同然だった。一般表記の 先々月 を供給する。
        // せんせんしゅう は踊り字なし版すら辞書に無い(ユーザー報告 2613)
        "せんせんげつ": ["先々月"],
        "せんせんしゅう": ["先々週"],
        // せんしゅう: 単文節は 先週 が rank 0 なのに、連文節は LM unigram(先週 6896 ≫ 千秋 6200 /
        // 選集 6225 / 専修 6497)で 私も先週 が候補から消えていた(ユーザー報告 3141)。
        // Wikipedia は 千秋/選集/専修 を多く含むが、日常語は 先週。連文節用のボーナスと対で使う
        "せんしゅう": ["先週"],
        // うるちまい: うるち米 が現代の主表記(粳 は常用漢字外)。交ぜ書きの抑制に巻き込まれて
