        "どれも": ["どれも", "何れも"],
        // ならんで: 並んで(活用派生 OOV 7200)と かな ならん(6500)+で が同点(13640)になり、
        // 列挙順で かな が勝っていた。たくさんならんで → たくさんならんで(ユーザー報告 3134/3187)。
        // 標準語の ならんで は 並んで で、ならん(だめだ)+で は方言の言い回し
        "ならんで": ["並んで", "併んで", "列んで"],
        // おとそ: 単文節は お屠蘇 が先頭なのに、連文節は 音祖(人名収穫)に負けて
        // おとそでも → 音祖でも になっていた(ユーザー報告 3187)
        "おとそ": ["お屠蘇"],
        // おしい: 単文節は 惜しい が rank 0 なのに、連文節は LM unigram(押井 6536 < 惜しい 7489)で
        // 監督名が先に出ていた。かげがおしい → 影が押井(ユーザー報告 3182)
        "おしい": ["惜しい", "おしい", "押井"],
        // そこに: 底荷(船舶のバラスト)が先頭だった。指示語のかなが実勢(ユーザー指定 2606)
        "そこに": ["そこに", "底に", "其処に", "底荷"],
        // てんじて: 点じて が先頭だった。転じて(話題を転じて 等)が実勢(ユーザー指定 2606)
        "てんじて": ["転じて", "点じて"],
        "かんする": ["関する", "冠する", "箝する", "緘する", "關する", "姦する"],
        // 基底に並びを宣言しても て形の派生には伝わらなかったので、活用形側にも置く
        "かんして": ["関して", "冠して", "箝して", "緘して", "關して", "姦して"],
