        // 例は/零は(合成)を先頭に、かな・名前群は後方へ自然降格(2529)
        "れいは": ["例は", "零は"],
        // ちしま/からふと: カタカナ表記ゆれの word_cost が異常に低い(チシマ4528/千島7515、
