        "はなしか": ["話か"],
        // めど: 変種は {目処, めど, メド} の表記側で出す(連語 めどが立つ とセット。
        // メド の連文節カタカナ強調抑制は seed 掲載で免除される)(ユーザ指定 2559)
        "めど": ["目処", "めど", "メド"],
