        // 単独入力する語のうち確実に困るものを抽出した(ユーザ指定 2564)
        "なみだ": ["涙", "なみだ"],
        "あいだ": ["間", "あいだ"],
        "ちから": ["力", "ちから"],
        "いけ": ["池", "いけ"],
        "ふだ": ["札", "ふだ"],
        // すごーい: カタカナ(スゴ〜イ/スゴーイ 4283)が かな(8156)より圧倒的に安く先頭を取る。
