        // カタカナも候補に残す(ユーザ指定 2564)
        "すごーい": ["すごーい", "スゴーイ", "スゴ〜イ"],
        // からだ: 体 は word_cost 2888(カラダ と最安タイ)・dict rank0・LM 4545 なのに
        // 候補に出なかった。単漢字は seed 掲載時のみ優遇される設計(applySeedSingleKanji
