        // 連文節でも から(助詞 LM2848)+だ の分割が勝つ(ユーザ指定 2564)
        "からだ": ["体", "身体", "からだ"],
        // せいせい: dictionary_entries の rank が 整斉/世世/清々/正々/済々… の順で、
        // LM で圧倒的に高頻度な 生成(4824)/精製(6032) が9位・10位に沈んでいた。
        // 製成 は sacoche 登録(酒造用語)で先頭に出ていたが日常語を優先する(ユーザ指定 2564)
        "せいせい": ["生成", "精製", "製成", "清々", "正々"],
        // やわらかい: word_cost は 軟らかい(7600) < 柔らかい(8919) だが LM は逆
        // (柔6251 < 軟6988)。活用形は word_costs に無く基底の並びを継ぐため
        // やわらかくて→軟らかくて になる。食感は 柔らかい が標準(ユーザ指定 2564)
        "やわらかい": ["やわらかい", "柔らかい", "軟らかい"],
        // かまぼこ: word_cost は 蒲鉾/カマボコ が同値(4187)で かな は9219 だが、LM unigram が
