        // 食品名は漢字表記を先頭に(ユーザ指定 2564)
        "かまぼこ": ["蒲鉾", "かまぼこ", "カマボコ"],
        // はやり: 流行(3455)が 流行り(7193)より安く、送りがな無しが先頭だった。名詞の
        // 「はやり」は送りがな付きが日常表記(ユーザ指定 2564)
        "はやり": ["流行り", "流行"],
        // のずるそうじ: そうじ は 掃除/相似 が同値(6518)で、LM も 相似6391 < 掃除6433 の
