        // なるため、残したい表記を全部並べる(ユーザ指定 2564)
        "のずるそうじ": ["ノズル掃除", "ノズルそうじ", "ノズル相似"],
        // すむのよ: すむ の word_cost が 住む(7228) < 済む(7946)。「〜ずに済む」と同型で、
        // 終助詞 のよ が付く句は 済む が主(ユーザ指定 2564)
        "すむのよ": ["済むのよ", "住むのよ"],
        // だねえ: {打ねえ, 駄ねえ, 惰ねえ, 堕ねえ, 舵ねえ} と当て字ばかりだった。断定+終助詞の
        // 句はかなが正書(ユーザ指定 2564)
        "だねえ": ["だねえ"],
        // なるほどー: なるほ の抑制後も なる+保+どー(成る保どー/鳴る保どー)に割られる。
        // 末尾長音の一般ルールは終助詞クラスタ等と衝突して8件のテストを壊したため、
        // 実用頻度の高い形だけ seed で1ノード化する(ユーザ指定 2564)
        "なるほどー": ["なるほどー"],
        "なるほどーー": ["なるほどーー"],
        // やる: かな やる(8372)が 遣る/ヤル(5971) に負けて基底4位。活用形の keepKana 判定は
        // 基底読みが seed かな先頭かで決まるので、やって/やった 等をかな維持にするために
