        // 消して候補ゼロにするので採らない(ユーザ指定 2564)
        "やる": ["やる"],        // くいにいきませんか: くい の word_cost が 悔い(7159) < 食い(9019) で
        // 悔いに行きませんか が先頭だった(ユーザ指定 2564)
        "くいにいきませんか": ["食いに行きませんか", "食いにいきませんか"],        // かえるかなあ: {変えるかなあ, 蛙化なあ, 帰るかなあ, カエルかなあ, …} の順で
        // 買えるかなあ が7位。買える→帰る→変える の順に矯正(ユーザ指定 2564)
        "かえるかなあ": ["買えるかなあ", "帰るかなあ", "変えるかなあ"],        // なんでまた: {何で又, 何でまた, 何で股, なんで又, なんでまた} の順だった。
        // 日常表記の 何でまた を先頭、かな を2位へ(ユーザ指定 2564)
        "なんでまた": ["何でまた", "なんでまた"],        // つかわずにすむ: すむ の word_cost が 住む(7228) < 済む(7946) のため
        // 使わずに住む になる。「〜ずに済む」は済むが正しい(ユーザ指定 2564)
        "つかわずにすむ": ["使わずに済む", "使わずにすむ"],




        // ですもんね: です+門/物/紋+ね の合成が かな より先だった(ですかね と同型)。
        // かな句スパンを供給+ボーナスで先頭に(ユーザ指定 2559)
        "ですもんね": ["ですもんね"],
        // なるので: 連文節で 鳴る/成る+ので が かな なるので より先だった。理由・接続の
        // 用法はかなが主なので、句スパンのかな識別を供給+ボーナスで先頭に(ユーザ指定 2556)
        "なるので": ["なるので"],
        // ですかね: ですか の辞書が 出須賀(収穫wc10000)のみで、連文節が 出須賀ね に
        // なっていた。句スパンのかな識別を供給+ボーナスで先頭に(ユーザ指定 2556)
        "ですかね": ["ですかね"],
        // おもろまち: 那覇の地名(かなが正式表記)。ryukyu.plist=SecondVocab は単文節のみで、
        // 連文節は収穫底値 wc10496 の単ノードが お諸町 等の分割に負ける。a2 供給+
