        "おん": ["オン", "On", "恩", "温", "ON", "怨", "on"],  // ユーザ指定の順(3399。ユーザの「恨」は おん と読まないので 怨)
        // びょう は 秒(LM4933=最頻・助数詞)が辞書 word_cost 順で 鋲/眇 に沈む。秒 を先頭・鋲/病 続き。
