        "おりたたんで": ["折り畳んで", "折畳んで", "折りたたんで"],
        // なんて は辞書にかなのみ。何て を供給(かな先頭は維持)
        "なんて": ["なんて", "何て"],
        // なく はかな識別wcが10363(収穫底値)で、短spanかな床+底値unigram不信(2126)の
