        "ばい": ["倍", "杯"],
        // ちかい は 誓(レア名詞収穫)が dict rank0 で 近い より先頭だった
        "ちかい": ["近い", "誓い"],
        // みつかる/みつける は dict rank が 見付〜0<見つ〜1(現代の主表記は 見つ〜)
        "みつかる": ["見つかる", "見付かる"],
        "みつける": ["見つける", "見付ける"],
