        "はりわすれ": ["貼り忘れ", "張り忘れ"],
        "はりわすれる": ["貼り忘れる", "張り忘れる"],
        // はる は dict rank が 張る1<貼る4 だが、現代の入力では 貼る(ログ/リンク/写真を
        // 貼る)が主。かな先頭は維持しつつ 貼る>張る の順に(はったら 等の活用派生順にも効く)。
        // 春(LM最良)はスイープ残渣承認で かなの直後 に挿入(2548)
        "はる": ["はる", "春", "貼る", "張る"],
