        "ゆずか": ["柚花", "柚香"],
        // 何時 は Sudachi 正規化で いつ 読みのみ登録され、なんじ 読みが辞書に無い
        // (なんじ は 汝/南寺/名前収穫だけ)。時刻の 何時 を先頭供給し、汝 を次点に
        "なんじ": ["何時", "汝"],
        // (株)(rank0/wc2530)が 株式会社(rank1/wc7980)より先に出る並びの是正
        "かぶしきがいしゃ": ["株式会社", "(株)"],
