        // 僅差で勝つ(EOS床の一般化は 感じ 等カジュアル語彙を痛め不成立=2094検証済み)。
        // 句で先頭供給(文中では 雨の日もある 等が LM で正しく勝つ)
        "あめのひも": ["雨の日も", "雨の紐"],
