        // Sudachi は 片仮名/平仮名 を正規化形として持つため、候補ソースが normalisé だと
        // カタカナ が候補から落ちて 方かな(方+かな)になっていた。misc のかな識別 curated と併せて是正
        "ひらがな": ["ひらがな", "平仮名"],
        "かたかな": ["カタカナ", "片仮名"],
        // 学名カタカナを先頭に(dict rank0 の 甲虫 は こうちゅう が主読みで suppr+
