        // 似る を 煮る より前に(辞書は 煮る が rank0。派生 にてる/にてるね はこの順を継ぐ。ユーザ指定 3460)
        "にる": ["似る", "煮る"],
        // 繊月(細い月、雅語)が rank 先頭で 先月 の前に出ていた(ユーザ指定 3450)
