        // 恨念/妙年(仏教語・雅語)が rank 先頭で、今年/明年 が後ろに沈んでいた(ユーザ指定 3456)
        "こんねん": ["今年", "恨念", "根念"],
        "みょうねん": ["明年", "妙年"],
        // 朔日(ついたち)が rank 先頭で 昨日 の前に出ていた(ユーザ指定 3457)
        "さくじつ": ["昨日", "朔日"],
        // 辞書順は 継承→渓床→軽少→軽捷(語コストの僅差で LM 未収録の語が前に出ていた)。LM の頻度を見てユーザ指定(3498)
        "けいしょう": ["継承", "敬称", "軽傷", "軽症", "警鐘", "景勝", "形象", "慶尚", "桂昌", "敬章"],
