        "もちごめ": ["もち米", "餅米", "糯米", "モチ米"],
        // 2798 バッチ(ユーザ報告)
        "えー": ["えー", "エー"],  // 間投詞はかなが主(LM は エー6883<えー7649 でカタカナが先頭だった)
