        "だなあ": ["だなあ"],
        // つけめん(2833): 辞書順は 付け麺→付けめん→つけ麺→つけめん だが、実際の表記はほぼ つけ麺(ユーザ指定)
        "つけめん": ["つけ麺", "つけめん", "付け麺", "付けめん"],
