        "はんにち": ["半日", "反日"],  // 単文節は 半日 先頭なのに連文節で 反日程度(unigram 6955<6988)に負けていた
        // せんとう(2859、抜き取り検査): 辞書順は 銭湯→戦闘→剪灯→戦鬪→先頭、LM も 戦闘 5016<先頭 5473。
