    // 「入力全体がこの読みと完全一致した単文節のときだけ」出す特殊候補。
    // 通常 seed と違い、systemCandidates(=語幹・活用・連文節のノード列挙)には一切
    // 供給しない。候補生成の最上段(collectDirectCandidates)で reading 完全一致時のみ
    // マージするため、どうし→々し のような合成漏れや連文節への混入が起きない。
    // 用途: 踊り字(繰り返し記号)。々=同の字点、〃=ノノ点、ゝゞ=平仮名、ヽヾ=片仮名。
    // 用途2: よく使う約物(記号)。記号/数字モードに行かず読みで直接出すための最短経路。
    // スコア300で候補列の末尾寄りに付くため、通常の語(丸/星/掛ける 等)は一切押しのけない。
    // 表示層の最後尾送り(2810): 読みが完全一致する単文節の表示で、指定表層を絵文字・顔文字より後ろへ回す。
    // 候補としては残るので合成(ほんとだ/ほんとに 等)や連文節には影響しない。suppr(候補を消す)と
    // exactReadingOnlySeed(変換候補の末尾=補助候補より前)の中間の強さ
    static let presentationTailSeed: [String: [String]] = [
        // ほんと は口語でかなが正書。本当 は Sudachi(cost 2581)由来で 2 位に出ていた(ユーザ指定 2810)
        "ほんと": ["本当"]
    ]

    // 表示層の先頭そろえ(3772): 読みが完全一致する単文節の表示で、指定表層をこの順で先頭に並べる(無ければ供給)。
    // seed に書くと短い頻出読みは連文節の部品にも効き 油の層→油の僧 のように崩れるため、表示の最後だけで並べる
    static let presentationOrderSeed: [String: [String]] = [
        // 動詞 添う/沿う を 2・3 番めに(ユーザ判定 3772)。seed の そう は 層 を守るため据え置き
        "そう": ["そう", "添う", "沿う", "総"]
    ]

    static let exactReadingOnlySeed: [String: [String]] = [
        // 五択: ごたく=御託 の先頭は守り、完全一致時のみ末尾供給(2633)
        "ごたく": ["五択", "5択"],
        // 麹塵(装束色): 辞書の 麴塵 は正字 麴 の一括抑制で消えるため 麹 表記を末尾供給。
        // 青色 の先頭は守る(きくじん 読みは misc で先頭供給。2784)
        "あおいろ": ["麹塵"],
        // 樫琥良(泡盛の銘柄、ryukyu): suppr で連文節から外し、かっこいい 単独のときだけ末尾に(ユーザ指定 3743)
        "かっこいい": ["樫琥良"],
        // 阿刀(あとの): レア姓のsuppr+末尾再供給の二段構え(あとの 完全一致時のみ)
        "あとの": ["阿刀"],
        // 古代氏姓の の込み読み(阿刀 と同型の二段構え)
        "ふじわらの": ["藤原"],
        "みなもとの": ["源"],
        "たいらの": ["平"],
        // 岡(おかの)= 源 と同型の の込み読み(suppr+末尾再供給の二段構え。2637)
        "おかの": ["岡"],
        "どう": ["々"],
        "おなじ": ["々"],
        "くりかえし": ["々", "〃", "ゝ", "ゞ", "ヽ", "ヾ"],
        "おどりじ": ["々", "〃", "ゝ", "ゞ", "ヽ", "ヾ"],
        // 図形。〇(漢数字ゼロ)と ◯(囲み用の大丸)は混乱の元なので出さない
        "まる": ["○", "◎", "●"],
        "にじゅうまる": ["◎"],
        "くろまる": ["●"],
        "さんかく": ["△", "▲", "▽", "▼"],
