        // 矢印
        "やじるし": ["→", "←", "↑", "↓"],
        "みぎ": ["→"],
        "ひだり": ["←"],
        "うえ": ["↑"],
        "した": ["↓"],
        // 記号
        "こめ": ["※"],
        "こめじるし": ["※"],
        "ゆうびん": ["〒"],
        "しめ": ["〆"],
        "おんぷ": ["♪"],
