        "なみ": ["〜"],
        // Apple 記号(はプライベート領域 U+F8FF、Apple 端末でのみ表示される)
        "あっぷる": [""],
        "こまんど": ["⌘"],
        // 歴史文書表記(琉球の古表記)。単独変換の末尾でのみ供給し、合成・連文節には出さない
        "りゅうきゅう": ["瑠求", "留求", "流求"],
        // 古語の敬語動詞(御座います の語源)。読みは正当だが現代入力では雑音のため
        // suppr で辞書から外し、完全一致時のみ末尾供給(いますよね 等の合成には出さない)
        "います": ["坐す", "在す"],
        // カタカナ表記(イル=SudachiDict カタカナ源/入ル=京都の地名表記)。suppr で辞書から
        // 外し、いる 完全一致時のみ末尾供給(いるので 等の合成・連文節には出さない)
        "いる": ["イル", "入ル"],
        // 冠者(狂言用語)。suppr で辞書から外し(と+冠者 が とかじゃ〜 を乗っ取るため)、
        // かじゃ 完全一致時のみ末尾供給。かんじゃ 読みは辞書に残る
        "かじゃ": ["冠者"],
        // 御(接頭辞)/音(単独名詞でない読み)。suppr で辞書から外し(を→御/を→音 が
        // 変種枠から ON/On/on を押し出すため)、おん 完全一致時のみ末尾供給
        "おん": ["音", "御"],
        // ここ のレア人名収穫(辞書 rank13-23)。suppr で辞書から外し、ここ 完全一致時のみ
        // 末尾供給(ここでは/ここに 等の合成・連文節には出さない)
        "ここ": ["小恋", "小瑚", "小虹", "小香", "幸呼", "幸恋", "心湖", "湖々", "湖紅", "琥々", "瑚々"],
        // 甲虫 の主読みは こうちゅう。かぶとむし 読みでは学術的な別表記として完全一致時のみ
        // 末尾供給(かぶとむしも 等の合成には出さない)
        "かぶとむし": ["甲虫"],
        // サンガ(京都サンガ/僧伽)は さんが 完全一致時のみ末尾供給(敬称さん+が を守る)
        "さんが": ["サンガ"],
        // 蚕糸(絹糸)は さんし 完全一致時のみ末尾供給(敬称さん+しか の分割を守る。
        // ねろめさんしか→根路銘蚕糸か の preempt を排除)
        "さんし": ["蚕糸"],
        // 方面(かたも)は鳥取県湯梨浜町の地名のレア読み。表層 unigram(ほうめん用途)に
        // タダ乗りして連文節の区切りを奪うため、完全一致時のみ末尾供給
        "かたも": ["方面"],
        // みたに の姓グロブ。3char単ノードが みたにある→三田にある の [地名][に][ある]
        // locative を preempt するため suppr。著名姓は みたに 完全一致時のみ供給
        "みたに": ["三谷", "水谷", "三渓"],
        // 尺貫法の体積単位×漢数字(一〜十)。辞書に無い44複合を補う(ユーザー指定 2613)。
        // じっと/護国/発祥/実証/緑青 等の頻出語と衝突する読みが多いため、完全一致時のみ
        // 末尾供給のこの層に置く(合成・連文節へは一切漏れない)。頻用するなら選択学習で
        // 上位へ昇格する。じっこく→十石/いっしょう→一升/いっと→一斗 等は辞書に既在
        "いちごう": ["一合"],
        "にごう": ["二合"],
        "さんごう": ["三合"],
        "よんごう": ["四合"],
        "ななごう": ["七合"],
        "はちごう": ["八合"],
        "きゅうごう": ["九合"],
        "じゅうごう": ["十合"],
        "いっしゃく": ["一勺"],
        "にしゃく": ["二勺"],
        "さんしゃく": ["三勺"],
        "よんしゃく": ["四勺"],
        "ごしゃく": ["五勺"],
        "ろくしゃく": ["六勺"],
        "ななしゃく": ["七勺"],
        "はっしゃく": ["八勺"],
        "きゅうしゃく": ["九勺"],
        "じっしゃく": ["十勺"],
        "じゅっしゃく": ["十勺"],
        "にしょう": ["二升"],
        "よんしょう": ["四升"],
        "ごしょう": ["五升"],
        "ろくしょう": ["六升"],
        "ななしょう": ["七升"],
        "はっしょう": ["八升"],
        "きゅうしょう": ["九升"],
        "じっしょう": ["十升"],
        "じゅっしょう": ["十升"],
        "にと": ["二斗"],
        "さんと": ["三斗"],
        "よんと": ["四斗"],
        "ななと": ["七斗"],
        "きゅうと": ["九斗"],
        "じっと": ["十斗"],
        "じゅっと": ["十斗"],
        "いっこく": ["一石"],
        "にこく": ["二石"],
        "さんごく": ["三石"],
        "よんこく": ["四石"],
        "ごこく": ["五石"],
        "ななこく": ["七石"],
        "はちこく": ["八石"],
        "きゅうこく": ["九石"],
        "じゅっこく": ["十石"]
    ]
}
